212	static int qcprobe(struct usb_serial *serial, const struct usb_device_id *id)
213	{
214		struct usb_host_interface *intf = serial->interface->cur_altsetting;
215		struct device *dev = &serial->dev->dev;
216		int retval = -ENODEV;
217		__u8 nintf;
218		__u8 ifnum;
219		int altsetting = -1;
220		bool sendsetup = false;
221	
222		/* we only support vendor specific functions */
223		if (intf->desc.bInterfaceClass != USB_CLASS_VENDOR_SPEC)
224			goto done;
225	
226		nintf = serial->dev->actconfig->desc.bNumInterfaces;
227		dev_dbg(dev, "Num Interfaces = %d\n", nintf);
228		ifnum = intf->desc.bInterfaceNumber;
229		dev_dbg(dev, "This Interface = %d\n", ifnum);
230	
231		if (nintf == 1) {
232			/* QDL mode */
233			/* Gobi 2000 has a single altsetting, older ones have two */
234			if (serial->interface->num_altsetting == 2)
235				intf = &serial->interface->altsetting[1];
236			else if (serial->interface->num_altsetting > 2)
237				goto done;
238	
239			if (intf->desc.bNumEndpoints == 2 &&
240			    usb_endpoint_is_bulk_in(&intf->endpoint[0].desc) &&
241			    usb_endpoint_is_bulk_out(&intf->endpoint[1].desc)) {
242				dev_dbg(dev, "QDL port found\n");
243	
244				if (serial->interface->num_altsetting == 1)
245					retval = 0; /* Success */
246				else
247					altsetting = 1;
248			}
249			goto done;
250	
251		}
252	
253		/* default to enabling interface */
254		altsetting = 0;
255	
256		/*
257		 * Composite mode; don't bind to the QMI/net interface as that
258		 * gets handled by other drivers.
259		 */
260	
261		switch (id->driver_info) {
262		case QCSERIAL_G1K:
263			/*
264			 * Gobi 1K USB layout:
265			 * 0: DM/DIAG (use libqcdm from ModemManager for communication)
266			 * 1: serial port (doesn't respond)
267			 * 2: AT-capable modem port
268			 * 3: QMI/net
269			 */
270			if (nintf < 3 || nintf > 4) {
271				dev_err(dev, "unknown number of interfaces: %d\n", nintf);
272				altsetting = -1;
273				goto done;
274			}
275	
276			if (ifnum == 0) {
277				dev_dbg(dev, "Gobi 1K DM/DIAG interface found\n");
278				altsetting = 1;
279			} else if (ifnum == 2)
280				dev_dbg(dev, "Modem port found\n");
281			else
282				altsetting = -1;
283			break;
284		case QCSERIAL_G2K:
285			/* handle non-standard layouts */
286			if (nintf == 5 && id->idProduct == QUECTEL_EC20_PID) {
287				altsetting = handle_quectel_ec20(dev, ifnum);
288				goto done;
289			}
290	
291			/*
292			 * Gobi 2K+ USB layout:
293			 * 0: QMI/net
294			 * 1: DM/DIAG (use libqcdm from ModemManager for communication)
295			 * 2: AT-capable modem port
296			 * 3: NMEA
297			 */
298			if (nintf < 3 || nintf > 4) {
299				dev_err(dev, "unknown number of interfaces: %d\n", nintf);
300				altsetting = -1;
301				goto done;
302			}
303	
304			switch (ifnum) {
305			case 0:
306				/* Don't claim the QMI/net interface */
307				altsetting = -1;
308				break;
309			case 1:
310				dev_dbg(dev, "Gobi 2K+ DM/DIAG interface found\n");
311				break;
312			case 2:
313				dev_dbg(dev, "Modem port found\n");
314				break;
315			case 3:
316				/*
317				 * NMEA (serial line 9600 8N1)
318				 * # echo "\$GPS_START" > /dev/ttyUSBx
319				 * # echo "\$GPS_STOP"  > /dev/ttyUSBx
320				 */
321				dev_dbg(dev, "Gobi 2K+ NMEA GPS interface found\n");
322				break;
323			}
324			break;
325		case QCSERIAL_SWI:
326			/*
327			 * Sierra Wireless layout:
328			 * 0: DM/DIAG (use libqcdm from ModemManager for communication)
329			 * 2: NMEA
330			 * 3: AT-capable modem port
331			 * 8: QMI/net
332			 */
333			switch (ifnum) {
334			case 0:
335				dev_dbg(dev, "DM/DIAG interface found\n");
336				break;
337			case 2:
338				dev_dbg(dev, "NMEA GPS interface found\n");
339				break;
340			case 3:
341				dev_dbg(dev, "Modem port found\n");
342				sendsetup = true;
343				break;
344			default:
345				/* don't claim any unsupported interface */
346				altsetting = -1;
347				break;
348			}
349			break;
350		case QCSERIAL_HWI:
351			/*
352			 * Huawei devices map functions by subclass + protocol
353			 * instead of interface numbers. The protocol identify
354			 * a specific function, while the subclass indicate a
355			 * specific firmware source
356			 *
357			 * This is a blacklist of functions known to be
358			 * non-serial.  The rest are assumed to be serial and
359			 * will be handled by this driver
360			 */
361			switch (intf->desc.bInterfaceProtocol) {
362				/* QMI combined (qmi_wwan) */
363			case 0x07:
364			case 0x37:
365			case 0x67:
366				/* QMI data (qmi_wwan) */
367			case 0x08:
368			case 0x38:
369			case 0x68:
370				/* QMI control (qmi_wwan) */
371			case 0x09:
372			case 0x39:
373			case 0x69:
374				/* NCM like (huawei_cdc_ncm) */
375			case 0x16:
376			case 0x46:
377			case 0x76:
378				altsetting = -1;
379				break;
380			default:
381				dev_dbg(dev, "Huawei type serial port found (%02x/%02x/%02x)\n",
382					intf->desc.bInterfaceClass,
383					intf->desc.bInterfaceSubClass,
384					intf->desc.bInterfaceProtocol);
385			}
386			break;
387		default:
388			dev_err(dev, "unsupported device layout type: %lu\n",
389				id->driver_info);
390			break;
391		}
392	
393	done:
394		if (altsetting >= 0) {
395			retval = usb_set_interface(serial->dev, ifnum, altsetting);
396			if (retval < 0) {
397				dev_err(dev,
398					"Could not set interface, error %d\n",
399					retval);
400				retval = -ENODEV;
401			}
402		}
403	
404		if (!retval)
405			usb_set_serial_data(serial, (void *)(unsigned long)sendsetup);
406	
407		return retval;
408	}
